class TokenizerCachingDecorator:
    def __init__(self, tokenizer, cache_size=1000):
        self.tokenizer = tokenizer
        self.cache_size = cache_size
        self.encode_cache = {}
        self.decode_cache = {}

    def encode(self, text, add_special_tokens=True):
        cache_key = (text, add_special_tokens)
        if cache_key in self.encode_cache:
            return self.encode_cache[cache_key]
        result = self.tokenizer.encode(text, add_special_tokens)
        if len(self.encode_cache) >= self.cache_size:
            self.encode_cache.pop(next(iter(self.encode_cache)))
        self.encode_cache[cache_key] = result
        return result
